def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def subtreeMedianSum(tree):
    val, left, right = parse(tree)
    n = len(val)
    size = [1] * n
    for u in range(n - 1, -1, -1):
        for c in (left[u], right[u]):
            if c != -1:
                size[u] += size[c]
    order = []          # inorder sequence of node ids
    stack, u = [], 0
    while stack or u != -1:
        while u != -1:
            stack.append(u)
            u = left[u]
        u = stack.pop()
        order.append(u)
        u = right[u]
    seq = [val[u] for u in order]
    total = 0
    for pos, u in enumerate(order):
        lsize = size[left[u]] if left[u] != -1 else 0
        start = pos - lsize
        total += seq[start + (size[u] - 1) // 2]
    return total
